package pl.zagranietyper.repository;import java.sql.*;import java.util.*;
public final class FootballTeamToAdvanceCandidateRepository {private final Database db;public FootballTeamToAdvanceCandidateRepository(Database d){db=d;}public List<Candidate>find(){String q="SELECT bl.id,bl.bet_id,bl.tip_title,f.fixture_id,f.league_id,f.league_name,f.season,f.round,f.home_team_id,f.home_team_name,f.away_team_id,f.away_team_name FROM bet_legs bl JOIN bets b ON b.id=bl.bet_id AND b.active JOIN api_football_fixtures f ON f.fixture_id=bl.resolved_external_event_id::bigint WHERE bl.active AND bl.resolved_provider='API_FOOTBALL' AND bl.settlement_status='PENDING' AND bl.settlement_source='NONE' AND f.status_short IN('FT','AET','PEN') AND lower(bl.tip_title)~'awans|zakwalifik' ORDER BY bl.id";try(Connection c=db.openConnection()){c.setReadOnly(true);try(var p=c.prepareStatement(q);var r=p.executeQuery()){List<Candidate>o=new ArrayList<>();while(r.next())o.add(new Candidate(r.getLong(1),r.getLong(2),r.getString(3),r.getLong(4),r.getLong(5),r.getString(6),r.getInt(7),r.getString(8),r.getLong(9),r.getString(10),r.getLong(11),r.getString(12)));return o;}}catch(SQLException e){throw new IllegalStateException(e);}}public record Candidate(long legId,long betId,String title,long fixtureId,long leagueId,String leagueName,int season,String round,long homeId,String homeName,long awayId,String awayName){} }
